<source_code>
#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdio>
using namespace std;

typedef long long ll;

const ll MOD = 1000000007;
const ll MOD2 = 998244353;

ll n;

// Count numbers with prefix 'pre' in lexicographic order from 1 to n
ll count_with_prefix(ll pre) {
    ll cnt = 0;
    ll start = pre;
    if (start == 0) start = 1;

    while (start <= n) {
        ll end = start + 1;
        while (end <= n && to_string(end).find(to_string(start)) == 0) {
            end++;
        }
        cnt += min(end, n + 1) - start;
        start *= 10;
    }
    return cnt;
}

// Get the lexicographic rank of number x among numbers 1 to n
ll get_lex_rank(ll x) {
    ll rank = 1;
    for (ll i = 1; i < x; i++) {
        if (to_string(i) < to_string(x)) {
            rank++;
        }
    }
    return rank;
}

// Calculate sum of (i - a_i) mod 998244353 for i from 1 to n
// where a_i is the i-th element in lexicographically sorted array of [1..n]
ll solve() {
    vector<ll> a;
    for (ll i = 1; i <= n; i++) {
        a.push_back(i);
    }

    // Sort lexicographically
    sort(a.begin(), a.end(), [](ll x, ll y) {
        return to_string(x) < to_string(y);
    });

    ll sum = 0;
    for (ll i = 1; i <= n; i++) {
        ll diff = (i - a[i-1]) % MOD2;
        if (diff < 0) diff += MOD2;
        sum = (sum + diff) % MOD;
    }

    return sum;
}

int main() {
    scanf("%lld", &n);

    // For small n, use direct simulation
    if (n <= 10000) {
        printf("%lld\n", solve());
        return 0;
    }

    // For larger n, use optimized approach
    vector<ll> a;
    for (ll i = 1; i <= min(n, 10000LL); i++) {
        a.push_back(i);
    }

    sort(a.begin(), a.end(), [](ll x, ll y) {
        return to_string(x) < to_string(y);
    });

    ll sum = 0;
    for (ll i = 1; i <= min(n, 10000LL); i++) {
        ll diff = (i - a[i-1]) % MOD2;
        if (diff < 0) diff += MOD2;
        sum = (sum + diff) % MOD;
    }

    // For larger n, we need to handle the rest efficiently
    // But since n can be up to 10^10, we need a smarter approach
    // The key insight is to generate numbers in lexicographic order

    // Let's use a different approach: generate numbers in lexicographic order
    vector<ll> lex_order;
    function<void(ll)> generate = [&](ll cur) {
        if (cur > 0 && cur <= n) {
            lex_order.push_back(cur);
        }
        if (cur > n) return;
        for (int d = 0; d <= 9; d++) {
            if (cur == 0 && d == 0) continue;
            generate(cur * 10 + d);
        }
    };

    generate(0);

    // Now calculate the sum
    for (ll i = 0; i < lex_order.size(); i++) {
        ll pos = i + 1;
        ll val = lex_order[i];
        ll diff = (pos - val) % MOD2;
        if (diff < 0) diff += MOD2;
        sum = (sum + diff) % MOD;
    }

    printf("%lld\n", sum);

    return 0;
}
